-- TASK-0080. Generated by Supabase CLI 2.121.0; proposed only, never auto-apply.
-- Requires existing 0000/0001 guild schema; independent of economy 0009/0010.
DO $$ BEGIN
  IF to_regprocedure('extensions.digest(text,text)') IS NULL OR
     to_regprocedure('extensions.gen_random_bytes(integer)') IS NULL THEN
    RAISE EXCEPTION 'Requires pgcrypto in extensions; review target before applying';
  END IF;
END $$;
CREATE SCHEMA guild_invite_private;
REVOKE ALL ON SCHEMA guild_invite_private FROM PUBLIC, anon;
GRANT USAGE ON SCHEMA guild_invite_private TO authenticated;

CREATE TABLE guild_invite_private.link_invites (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  guild_id uuid NOT NULL REFERENCES public.guilds(id),
  leader_traveler_id uuid NOT NULL REFERENCES public.travelers(id),
  token_hash bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  CHECK (expires_at > created_at AND expires_at <= created_at + interval '7 days')
);
CREATE INDEX link_invites_active_guild_idx
  ON guild_invite_private.link_invites(guild_id, expires_at) WHERE revoked_at IS NULL;
ALTER TABLE guild_invite_private.link_invites ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON guild_invite_private.link_invites FROM PUBLIC, anon, authenticated;

CREATE FUNCTION guild_invite_private.require_account() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM auth.users WHERE id = auth.uid() AND NOT coalesce(is_anonymous, false)
  ) THEN RAISE EXCEPTION 'Account required' USING ERRCODE = '42501'; END IF;
END $$;

CREATE FUNCTION guild_invite_private.leader_guild(p_leader uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE guild_key uuid;
BEGIN
  PERFORM guild_invite_private.require_account();
  SELECT g.id INTO guild_key FROM public.guilds g
    JOIN public.guild_members gm ON gm.guild_id = g.id
    JOIN public.travelers t ON t.id = gm.traveler_id
    WHERE t.id = p_leader AND t.user_id = auth.uid()
      AND gm.role = 'leader' AND gm.status = 'active' AND g.status = 'active'
    FOR UPDATE OF g;
  IF guild_key IS NULL THEN RAISE EXCEPTION 'Leader required' USING ERRCODE = '42501'; END IF;
  RETURN guild_key;
END $$;

CREATE FUNCTION guild_invite_private.valid_invite(p_token text)
RETURNS guild_invite_private.link_invites
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE invite_row guild_invite_private.link_invites;
BEGIN
  IF p_token IS NULL OR p_token !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invite unavailable' USING ERRCODE = 'P0002';
  END IF;
  SELECT i.* INTO invite_row FROM guild_invite_private.link_invites i
    JOIN public.guilds g ON g.id = i.guild_id
    JOIN public.guild_members gm ON gm.guild_id = g.id AND gm.traveler_id = i.leader_traveler_id
    WHERE i.token_hash = extensions.digest(p_token, 'sha256')
      AND i.revoked_at IS NULL AND i.expires_at > clock_timestamp()
      AND g.status = 'active' AND gm.role = 'leader' AND gm.status = 'active'
    FOR SHARE OF i, g, gm;
  -- A row lock can wait beyond expiry even when the WHERE matched before waiting.
  IF NOT FOUND OR invite_row.expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'Invite unavailable' USING ERRCODE = 'P0002';
  END IF;
  RETURN invite_row;
END $$;

CREATE FUNCTION guild_invite_private.create_invite(p_leader uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE guild_key uuid; raw_token text; new_row guild_invite_private.link_invites;
  issued_at timestamptz := clock_timestamp();
BEGIN
  guild_key := guild_invite_private.leader_guild(p_leader);
  IF (SELECT count(*) FROM guild_invite_private.link_invites
      WHERE guild_id = guild_key AND revoked_at IS NULL AND expires_at > clock_timestamp()) >= 10 THEN
    RAISE EXCEPTION 'Active invite limit reached' USING ERRCODE = '54000';
  END IF;
  raw_token := encode(extensions.gen_random_bytes(32), 'hex');
  INSERT INTO guild_invite_private.link_invites(guild_id, leader_traveler_id, token_hash, created_at, expires_at)
    VALUES (guild_key, p_leader, extensions.digest(raw_token, 'sha256'), issued_at, issued_at + interval '7 days')
    RETURNING * INTO new_row;
  RETURN jsonb_build_object('id', new_row.id, 'token', raw_token, 'expires_at', new_row.expires_at);
END $$;

CREATE FUNCTION guild_invite_private.list_invites(p_leader uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE guild_key uuid;
BEGIN
  guild_key := guild_invite_private.leader_guild(p_leader);
  RETURN coalesce((SELECT jsonb_agg(to_jsonb(v)) FROM (
    SELECT id, created_at, expires_at, revoked_at FROM guild_invite_private.link_invites
    WHERE guild_id = guild_key ORDER BY created_at DESC LIMIT 50
  ) v), '[]'::jsonb);
END $$;

CREATE FUNCTION guild_invite_private.resolve_invite(p_token text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE invite_row guild_invite_private.link_invites; guild_name text;
BEGIN
  PERFORM guild_invite_private.require_account();
  invite_row := guild_invite_private.valid_invite(p_token);
  SELECT name INTO guild_name FROM public.guilds WHERE id = invite_row.guild_id;
  RETURN jsonb_build_object('guild_name', guild_name, 'expires_at', invite_row.expires_at);
END $$;

-- Possession of a valid limited invite allows only this minimal pre-login preview.
CREATE FUNCTION guild_invite_private.preview_invite(p_token text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE invite_row guild_invite_private.link_invites; guild_name text;
BEGIN
  invite_row := guild_invite_private.valid_invite(p_token);
  SELECT name INTO guild_name FROM public.guilds WHERE id = invite_row.guild_id;
  RETURN jsonb_build_object('guild_name', guild_name, 'expires_at', invite_row.expires_at);
END $$;

CREATE FUNCTION guild_invite_private.request_invite(p_token text, p_traveler uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE invite_row guild_invite_private.link_invites;
BEGIN
  PERFORM guild_invite_private.require_account();
  invite_row := guild_invite_private.valid_invite(p_token);
  IF NOT public.owns_traveler(p_traveler) THEN
    RAISE EXCEPTION 'Traveler not owned' USING ERRCODE = '42501';
  END IF;
  -- Existing RPC creates/reuses a PENDING request; only its normal review may add membership.
  RETURN public.request_join_guild(invite_row.guild_id, p_traveler);
END $$;

CREATE FUNCTION guild_invite_private.revoke_invite(p_id uuid, p_leader uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE guild_key uuid;
BEGIN
  guild_key := guild_invite_private.leader_guild(p_leader);
  UPDATE guild_invite_private.link_invites SET revoked_at = coalesce(revoked_at, clock_timestamp())
    WHERE id = p_id AND guild_id = guild_key;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invite unavailable' USING ERRCODE = 'P0002'; END IF;
END $$;

CREATE FUNCTION public.create_guild_link_invite(p_leader_traveler_id uuid) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT guild_invite_private.create_invite(p_leader_traveler_id) $$;
CREATE FUNCTION public.list_guild_link_invites(p_leader_traveler_id uuid) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT guild_invite_private.list_invites(p_leader_traveler_id) $$;
CREATE FUNCTION public.resolve_guild_link_invite(p_token text) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT guild_invite_private.resolve_invite(p_token) $$;
CREATE FUNCTION public.preview_guild_link_invite(p_token text) RETURNS jsonb
LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT guild_invite_private.preview_invite(p_token) $$;
CREATE FUNCTION public.request_guild_link_invite(p_token text, p_traveler_id uuid) RETURNS uuid
LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT guild_invite_private.request_invite(p_token, p_traveler_id) $$;
CREATE FUNCTION public.revoke_guild_link_invite(p_invite_id uuid, p_leader_traveler_id uuid) RETURNS void
LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT guild_invite_private.revoke_invite(p_invite_id, p_leader_traveler_id) $$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA guild_invite_private FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.preview_guild_link_invite(text) FROM PUBLIC, anon, authenticated;
GRANT USAGE ON SCHEMA guild_invite_private TO anon;
GRANT EXECUTE ON FUNCTION guild_invite_private.preview_invite(text), public.preview_guild_link_invite(text) TO anon, authenticated;
GRANT EXECUTE ON FUNCTION guild_invite_private.create_invite(uuid), guild_invite_private.list_invites(uuid),
  guild_invite_private.resolve_invite(text), guild_invite_private.request_invite(text,uuid),
  guild_invite_private.revoke_invite(uuid,uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.create_guild_link_invite(uuid), public.list_guild_link_invites(uuid),
  public.resolve_guild_link_invite(text), public.request_guild_link_invite(text,uuid),
  public.revoke_guild_link_invite(uuid,uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_guild_link_invite(uuid), public.list_guild_link_invites(uuid),
  public.resolve_guild_link_invite(text), public.request_guild_link_invite(text,uuid),
  public.revoke_guild_link_invite(uuid,uuid) TO authenticated;
